CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  owner TEXT NOT NULL,
  balance INTEGER NOT NULL CHECK (balance >= 0)
);

INSERT INTO accounts (owner, balance) VALUES ('Анна', 500), ('Борис', 200);

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

SELECT owner, balance FROM accounts ORDER BY id;

BEGIN;
DELETE FROM accounts;
SELECT COUNT(*) AS inside FROM accounts;
ROLLBACK;
SELECT COUNT(*) AS after FROM accounts;

CREATE TABLE log (
  id INTEGER PRIMARY KEY,
  msg TEXT NOT NULL
);

BEGIN;
INSERT INTO log (msg) VALUES ('начало');
SAVEPOINT step;
INSERT INTO log (msg) VALUES ('эксперимент');
ROLLBACK TO step;
COMMIT;

SELECT msg FROM log;

CREATE TABLE log (
  id INTEGER PRIMARY KEY,
  msg TEXT NOT NULL
);

-- без BEGIN каждая команда фиксируется сама:
INSERT INTO log (msg) VALUES ('раз');
INSERT INTO log (msg) VALUES ('два');

-- с BEGIN — одна общая фиксация:
BEGIN;
INSERT INTO log (msg) VALUES ('три');
INSERT INTO log (msg) VALUES ('четыре');
COMMIT;

CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  stock INTEGER NOT NULL
);

INSERT INTO products (name, stock) VALUES ('Чай', 1);

-- проверка и списание одной командой
UPDATE products SET stock = stock - 1 WHERE id = 1 AND stock > 0;
SELECT changes() AS sold;

